module scrambler(
    input               clk,
    input               rst_n,
    input               en,
    input   [63:0]      data_in,
    output              flag,
    output  [63:0]      data_out
);

parameter   max         = 258;
reg     [15:0]  count   = 16'd0;

parameter   IDLE        = 3'b001;
parameter   ACTIVE      = 3'b010;
parameter   END         = 3'b100;

reg     [2:0]   state;
reg     [2:0]   next_state;

parameter   init    = 64'h87654321abcd9536;

reg     [63:0]  data_in_d0;
reg     [63:0]  scr_out;
wire    [63:0]  S;

wire    [64:0]  B   [0:64];
wire    [64:0]  D;
reg     [64:0]  Q   = {1'b0, init};


always @(posedge clk or negedge rst_n)
begin
    if (~rst_n)
        state   <= IDLE;
    else
        state   <= next_state;
end

always @(posedge clk or negedge rst_n)
begin
    if (~rst_n)
        count   <= 16'd0;
    else if (state == ACTIVE)
        count   <= count + 1'b1;
    else
        count   <= 16'd0;
end

always @(*)
begin
    case(state)
        IDLE:           begin
                            if (en)
                                next_state  <= ACTIVE;
                            else
                                next_state  <= IDLE;
                        end
        ACTIVE:         begin
                            if (count < max)
                                next_state  <= ACTIVE;
                            else
                                next_state  <= END;
                        end
        END:            next_state  <= IDLE;
        default:        next_state  <= IDLE;
    endcase
end

always @(posedge clk or negedge rst_n)
begin
    if (~rst_n)
        data_in_d0      <= 64'b0;
    else
        data_in_d0      <= data_in;
end

always @(posedge clk or negedge rst_n)
begin
    if (~rst_n)
        Q   <= {1'b0, init};
    else if (state == ACTIVE)
        Q   <= D;
    else
        Q   <= {1'b0, init};
end

always @(posedge clk or negedge rst_n)
begin
    if (~rst_n)
        scr_out     <= 64'd0;
    else if (state == ACTIVE)
        scr_out     <= data_in_d0 ^ S;
    else
        scr_out     <= 64'd0;
end

